export default {
  async fetch(request) {
    const url = new URL(request.url);
    let path;
    try { path = decodeURIComponent(url.pathname); } catch { return new Response('Bad request', {status:400}); }
    path = path.replace(/\/{2,}/g, '/');
    if (/^\/(wp-admin|wp-login\.php|wp-includes|wp-content|wp-cron\.php|xmlrpc\.php)(\/|$)/i.test(path))
      return new Response('Gone', {status:410});
    let target;
    if (path === '/' && /^\?s=[^&]+$/.test(url.search)) target = 'https://www.moreblossom.com/database';
    const key = path.endsWith('/') ? path.slice(0,-1) : path;
    target ??= exact.get(key);
    if (!target) {
      for (const [pattern, destination] of fallback) {
        const match = path.match(pattern);
        if (match) { target = destination.replace(/\$(\d+)/g, (_,n) => match[Number(n)] ?? ''); break; }
      }
    }
    target ??= 'https://www.moreblossom.com/';
    return new Response(null, {status:301, headers:{Location:new URL(target).href + url.search, 'X-Blossom-Redirect':'cloudflare-v1'}});
  }
};
